import { test, expect } from '@playwright/test';

test.describe('PayPal Payment Method Selection', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the payment page
    await page.goto('/checkout');

    // Wait for payment method section to be visible
    await page.getByRole('heading', { name: /payment method/i }).waitFor({ state: 'visible' });
  });

  test('should display PayPal as an available payment option', async ({ page }) => {
    // Verify PayPal option is visible on the page
    const paypalOption = page.getByRole('radio', { name: /paypal/i });
    await expect(paypalOption).toBeVisible();

    // Verify PayPal option is not disabled
    await expect(paypalOption).toBeEnabled();
  });

  test('should select PayPal as payment method and display PayPal-specific form', async ({ page }) => {
    // Click on PayPal radio button
    const paypalRadio = page.getByRole('radio', { name: /paypal/i });
    await paypalRadio.click();

    // Verify PayPal is selected
    await expect(paypalRadio).toBeChecked();

    // Verify PayPal-specific content appears
    const paypalSection = page.getByText(/paypal account/i);
    await expect(paypalSection).toBeVisible();
  });

  test('should show PayPal email input field when PayPal is selected', async ({ page }) => {
    // Select PayPal payment method
    const paypalRadio = page.getByRole('radio', { name: /paypal/i });
    await paypalRadio.click();

    // Verify email input field is visible
    const emailInput = page.getByLabel(/paypal email/i);
    await expect(emailInput).toBeVisible();

    // Verify email input is enabled for interaction
    await expect(emailInput).toBeEnabled();
  });

  test('should allow entering PayPal email and proceed to next step', async ({ page }) => {
    // Select PayPal payment method
    const paypalRadio = page.getByRole('radio', { name: /paypal/i });
    await paypalRadio.click();

    // Fill in PayPal email
    const emailInput = page.getByLabel(/paypal email/i);
    await emailInput.fill('user@example.com');

    // Verify email was entered correctly
    await expect(emailInput).toHaveValue('user@example.com');

    // Click continue/next button
    const continueButton = page.getByRole('button', { name: /continue|next/i });
    await continueButton.click();

    // Verify we've moved to the next step (PayPal confirmation or order review)
    const confirmationHeading = page.getByRole('heading', { name: /confirm|review|order/i });
    await expect(confirmationHeading).toBeVisible();
  });

  test('should deselect PayPal when another payment method is selected', async ({ page }) => {
    // Select PayPal first
    const paypalRadio = page.getByRole('radio', { name: /paypal/i });
    await paypalRadio.click();
    await expect(paypalRadio).toBeChecked();

    // Select credit card option instead
    const creditCardRadio = page.getByRole('radio', { name: /credit card|card/i });
    await creditCardRadio.click();

    // Verify PayPal is no longer selected
    await expect(paypalRadio).not.toBeChecked();

    // Verify credit card is now selected
    await expect(creditCardRadio).toBeChecked();

    // Verify PayPal-specific fields are hidden
    const paypalSection = page.getByText(/paypal account/i);
    await expect(paypalSection).not.toBeVisible();
  });

  test('should validate PayPal email format before proceeding', async ({ page }) => {
    // Select PayPal payment method
    const paypalRadio = page.getByRole('radio', { name: /paypal/i });
    await paypalRadio.click();

    // Fill in invalid email format
    const emailInput = page.getByLabel(/paypal email/i);
    await emailInput.fill('invalid-email');

    // Try to proceed
    const continueButton = page.getByRole('button', { name: /continue|next/i });
    await continueButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/invalid email|please enter a valid/i);
    await expect(errorMessage).toBeVisible();

    // Verify we're still on the same page
    const paymentHeading = page.getByRole('heading', { name: /payment method/i });
    await expect(paymentHeading).toBeVisible();
  });

  test('should persist PayPal selection when navigating back and forth', async ({ page }) => {
    // Select PayPal
    const paypalRadio = page.getByRole('radio', { name: /paypal/i });
    await paypalRadio.click();

    // Fill email
    const emailInput = page.getByLabel(/paypal email/i);
    await emailInput.fill('user@example.com');

    // Click continue
    const continueButton = page.getByRole('button', { name: /continue|next/i });
    await continueButton.click();

    // Wait for next page to load
    await page.waitForLoadState('networkidle');

    // Click back button
    const backButton = page.getByRole('button', { name: /back|previous/i });
    await backButton.click();

    // Verify PayPal is still selected
    await expect(paypalRadio).toBeChecked();

    // Verify email is still filled
    await expect(emailInput).toHaveValue('user@example.com');
  });
});
